    #if DEBUG
    private var designFixture = false
    func loadDesignFixture() {
        designFixture = true
        let scenario = ProcessInfo.processInfo.environment["DSH_BOT_DESIGN_STATE"] ?? "normal"
        let fixture = ["loading", "error"].contains(scenario) ? "empty" : scenario
        var json = Self.designFixtures[fixture] ?? Self.designFixtures["normal"]!
        if scenario == "scroll" || scenario == "scroll-profile",
           var object = try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any] {
            let profile = scenario == "scroll-profile"
            object["histories"] = ["chief": (1...(profile ? 96 : 24)).map { index in
                let text = profile
                    ? "历史消息 \(index)\n\n- **验证 Markdown 布局**，打开 `reports/report-\(index).md`。\n- [报告](https://example.com/report/\(index)) 包含两段正文。\n\n历史消息滚动时，标题、列表、链接和行内代码应保持同样的格式。" // i18n-ignore: 固定中文滚动测试样本
                    : "历史消息 \(index)\n\n用于验证离开会话底部后，可以一键回到最新消息。" // i18n-ignore: 固定中文滚动测试样本
                return ["id": "scroll-\(index)", "kind": "bot", "botId": "chief", "text": text]
            }]
            if let data = try? JSONSerialization.data(withJSONObject: object) {
                json = String(decoding: data, as: UTF8.self)
            }
        }
        if scenario == "role-keyboard",
           var object = try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any],
           var cached = object["snapshot"] as? [String: Any] {
            cached["roleSettingsSupported"] = true
            object["snapshot"] = cached
            if let data = try? JSONSerialization.data(withJSONObject: object) {
                json = String(decoding: data, as: UTF8.self)
            }
        }
        let preview = try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any]
        if let image = preview?["previewImageBase64"] as? String { designImageData = Data(base64Encoded: image) }
        _ = core.restoreCacheJson(json: json)
        let activation = core.activate(supported: true, connected: scenario != "empty")
        snapshot = activation.snapshot
        if scenario == "live-work", let work = preview?["previewWork"],
           let requestID = activation.requests.first(where: { $0.payload.contains("\"endpoint\":\"state\"") })?.correlationId,
           let data = try? JSONSerialization.data(withJSONObject: [
               "kind": "bot-result", "requestId": requestID, "endpoint": "state",
               "value": ["revision": 1, "unchanged": true, "work": work]
           ]) {
            snapshot = core.acceptJson(json: String(decoding: data, as: UTF8.self)).snapshot
        }
        if scenario == "page-parity", let value = preview?["previewState"],
           let requestID = activation.requests.first(where: { $0.payload.contains("\"endpoint\":\"state\"") })?.correlationId,
           let data = try? JSONSerialization.data(withJSONObject: [
               "kind": "bot-result", "requestId": requestID, "endpoint": "state", "value": value
           ]) {
            snapshot = core.acceptJson(json: String(decoding: data, as: UTF8.self)).snapshot
        }
        if scenario == "error" {
            for request in activation.requests {
                if let id = request.correlationId { snapshot = core.requestFailed(requestId: id, code: "bot-timeout").snapshot }
            }
        }
    }
    // 由 scripts/sync-bot-design-fixture.py 从可读 JSON 生成，仅用于 Debug 验收。
    private static let designFixtures: [String: String] = [
        "normal": String(data: Data(base64Encoded: "")!, encoding: .utf8)!,
        "long": String(data: Data(base64Encoded: "")!, encoding: .utf8)!,
        "empty": String(data: Data(base64Encoded: "ewogICJ2ZXJzaW9uIjogMSwKICAic25hcHNob3QiOiB7CiAgICAibWFpbkJvdElkIjogbnVsbCwKICAgICJjaGF0cyI6IFtdLAogICAgInNjaGVkdWxlcyI6IFtdLAogICAgInJlY2VudCI6IFtdCiAgfSwKICAiaGlzdG9yaWVzIjoge30sCiAgIm9wdGltaXN0aWMiOiB7fQp9")!, encoding: .utf8)!,
        "images": String(data: Data(base64Encoded: "")!, encoding: .utf8)!,
        "markdown-images": String(data: Data(base64Encoded: "")!, encoding: .utf8)!,
        "files": String(data: Data(base64Encoded: "")!, encoding: .utf8)!,
        "bubble-widths": String(data: Data(base64Encoded: "")!, encoding: .utf8)!,
