    private let core = SharedBotStore()
    private let gateway: GatewayClient
    private let images: MarkdownImageLoader
    private var observation: AnyCancellable?
    private var timeouts: [String: Task<Void, Never>] = [:]
    private var recovery: Task<Void, Never>?
    private var recoveryAttempts = 0
    private var saveTask: Task<Void, Never>?
    private let cacheQueue = DispatchQueue(label: "ai.dsh.bot-cache", qos: .utility)
    private let cacheURL: URL

    init(gateway: GatewayClient, profileID: String = "bot-ui-test", images: MarkdownImageLoader? = nil) {
        uploads = FileUploadController(gatewayID: profileID)
        self.gateway = gateway
        self.images = images ?? MarkdownImageLoader()
        self.images.sendBot = { [weak gateway] in gateway?.sendBotRequest($0) ?? false }
        let key = SHA256.hash(data: Data(profileID.utf8)).map { String(format: "%02x", $0) }.joined()
        cacheURL = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("BotMode", isDirectory: true).appendingPathComponent(key + ".json")
        if let bytes = try? Data(contentsOf: cacheURL), bytes.count <= 8_000_000 {
            _ = core.restoreCacheJson(json: String(decoding: bytes, as: UTF8.self))
        }
        snapshot = core.snapshot()
        uploads.changed = { [weak self] in self?.objectWillChange.send() }
        uploads.send = { [weak gateway] payload in gateway?.sendRequestPayload(payload, decorate: false) }
        uploads.reportError = { [weak self] message in self?.attachmentError = message }
        gateway.onBotFrame = { [weak self] json in self?.receive(json) }
        observation = gateway.$state.receive(on: DispatchQueue.main).sink { [weak self] state in
            guard let self else { return }
            #if DEBUG
            if self.designFixture { return }
            if case .failed(let reason) = state { self.testConnectionState = reason }
            else { self.testConnectionState = state.label }
            #endif
            if !state.isConnected {
                self.images.cancelAll()
                self.uploads.disconnected()
                self.submittedFileIDs.removeAll()
            } else if !self.uploads.supported {
                self.uploads.connected(sessionID: self.selectedSessionID, supported: gateway.supportsFileUploads)
            }
            self.apply(self.core.connectionChanged(supported: gateway.supportsBots, connected: state.isConnected))
        }
    }

    func activate() {
        #if DEBUG
        if designFixture { return }
        #endif
        apply(core.activate(supported: gateway.supportsBots, connected: gateway.state.isConnected))
    }
    func select(_ id: String?) {
        #if DEBUG
        if designFixture { snapshot = core.selectChat(id: id).snapshot; return }
        #endif
        apply(core.selectChat(id: id))
    }
    func setForeground(_ active: Bool) { apply(core.setForeground(active: active)) }
    func loadEarlier() { apply(core.loadEarlier()) }
    func searchChats(_ query: String) -> [BotChat] { core.searchChats(query: query) }
    var selectedSessionID: String? {
        snapshot.chats.first { $0.id == snapshot.selectedChatId }?.sessionId
    }

    func acceptUpload(_ frame: GatewayFrame) { uploads.accept(frame) }
    func clearAttachmentError() { attachmentError = nil }

    func importFiles(_ result: Result<[URL], Error>, target: String?) {
        guard let target, target == selectedSessionID, snapshot.attachmentsSupported else { return }
        switch result {
        case .success(let urls):
            uploads.select(sessionID: target, allowed: true)
            Task { await uploads.importFiles(urls) }
        case .failure(let error):
            if (error as NSError).code != NSUserCancelledError { attachmentError = error.localizedDescription }
        }
    }

    @discardableResult
    func send(_ text: String, displayText: String? = nil, images: [GatewayOutgoingImage] = []) -> String? {
        guard !uploads.preparing, uploads.drafts.isEmpty || (uploads.sessionID == selectedSessionID && uploads.canSend) else { return nil }
        let values = images.map { image in
            var value = ["mediaType": image.mediaType, "data": image.data.base64EncodedString()]
            value["name"] = image.name
            return value
        }
        guard let imageData = try? JSONEncoder().encode(values),
              let receiptData = try? JSONEncoder().encode(uploads.receipts) else { return nil }
        let transition = core.sendMentionMessage(text: text, displayText: displayText ?? text,
            imagesJson: String(decoding: imageData, as: UTF8.self),
            receiptsJson: String(decoding: receiptData, as: UTF8.self))
        let requestID = transition.requests.first?.correlationId
        if let requestID, !uploads.drafts.isEmpty {
            submittedFileIDs[requestID] = uploads.drafts.map(\.id)
        }
        apply(transition)
        return requestID
    }

