    func refresh() { recoveryAttempts = 0; apply(core.refresh()) }
    func answer(_ question: BotInteraction, selected: [String], custom: String) {
        let json = (try? JSONEncoder().encode(selected)).map { String(decoding: $0, as: UTF8.self) } ?? "[]"
        apply(core.answerQuestion(id: question.id, selectedJson: json, custom: custom))
