    #if DEBUG
    private var designOriginalFailure = ProcessInfo.processInfo.environment["DSH_BOT_IMAGE_FAIL_ONCE"] == "1"
    var designImageData: Data?
    #endif
    private let imageNamespace = UUID().uuidString
    var viewportCacheScope: String { "bot:" + imageNamespace }
    func imageContext(chatID: String, message: BotChatMessage) -> WorkspaceMarkdownImageContext {
        let refs = Dictionary(message.images.map { ("/__bot_image__/" + $0.attachmentId, $0) }, uniquingKeysWith: { first, _ in first })
        let sessionID = message.sessionId.isEmpty ? chatID : message.sessionId
        let load: @MainActor @Sendable (String, Bool) async throws -> Data = { [weak self] path, preview in
            guard let self else { throw CancellationError() }
            #if DEBUG
            if self.designFixture, let fixture = self.designImageData {
                if !preview && self.designOriginalFailure { self.designOriginalFailure = false; throw URLError(.cannotLoadFromNetwork) }
                return fixture
            }
            #endif
            if let ref = refs[path] {
                return try await self.images.loadBot(sessionID: ref.sessionId, attachmentID: ref.attachmentId, path: nil, author: nil, preview: preview)
            }
            return try await self.images.loadBot(sessionID: sessionID, attachmentID: nil, path: path, author: message.botId, preview: preview)
        }
        return WorkspaceMarkdownImageContext(id: imageNamespace + ":" + sessionID + ":" + (message.botId ?? ""), dimensions: { path in
            guard let ref = refs[path], ref.width > 0, ref.height > 0 else { return nil }
            return GatewayImageDimensions(width: Int(ref.width), height: Int(ref.height))
        }, loadOriginal: { path in try await load(path, false) }) { path in try await load(path, true) }
    }

    private func receive(_ json: String) {
        let frame = (try? JSONSerialization.jsonObject(with: Data(json.utf8))) as? [String: Any]
        if let id = frame?["requestId"] as? String {
            timeouts.removeValue(forKey: id)?.cancel()
            if let files = submittedFileIDs.removeValue(forKey: id) {
                if frame?["kind"] as? String == "bot-result" { uploads.accepted(files) }
                else if frame?["code"] as? String == "session/attachment-invalid" { uploads.invalidReceipts() }
            }
        }
        if images.acceptBot(json) { return }
        apply(core.acceptJson(json: json))
        if frame?["kind"] as? String == "bot-stream-reset", recoveryAttempts < 3 {
            recovery?.cancel()
            recoveryAttempts += 1
            let delay = recoveryAttempts * 2
            recovery = Task { [weak self] in
                do { try await Task.sleep(for: .seconds(delay)) } catch { return }
                guard let self, self.gateway.state.isConnected else { return }
                self.apply(self.core.refresh())
            }
        }
    }

    private func apply(_ transition: SharedBotTransition) {
        let target = selectedSessionID
        let wasAllowed = snapshot.attachmentsSupported && snapshot.writable
        snapshot = transition.snapshot
        let allowed = snapshot.attachmentsSupported && snapshot.writable
        if selectedSessionID != target || allowed != wasAllowed {
            uploads.select(sessionID: selectedSessionID, allowed: allowed)
        }
        #if DEBUG
        if designFixture { return }
        #endif
        saveTask?.cancel()
        saveTask = Task { [weak self] in
            do { try await Task.sleep(for: .milliseconds(600)) } catch { return }
            guard let self else { return }
            let data = Data(self.core.exportCacheJson().utf8)
            guard !data.isEmpty else { return }
            let url = self.cacheURL
            self.cacheQueue.async {
                do {
                    try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                    try data.write(to: url, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
                } catch { }
            }
        }
        for request in transition.requests {
            guard let id = request.correlationId else { continue }
            guard gateway.sendBotRequest(request.payload) else {
                submittedFileIDs.removeValue(forKey: id)
                snapshot = core.requestFailed(requestId: id, code: "not-connected").snapshot
                continue
            }
            timeouts[id]?.cancel()
            timeouts[id] = Task { [weak self] in
                do { try await Task.sleep(for: .seconds(32)) } catch { return }
                guard let self else { return }
                self.timeouts.removeValue(forKey: id)
                self.submittedFileIDs.removeValue(forKey: id)
                self.apply(self.core.requestFailed(requestId: id, code: "bot-timeout"))
            }
        }
    }
}

/// 首页复用 WorkspaceView 的品牌、连接、设置及抽屉；此处只负责助理内容。
struct BotModeView: View {
    @Environment(\.colorScheme) private var colorScheme
    @Environment(\.scenePhase) private var scenePhase
    @ObservedObject var model: BotModeModel
    let onStandardMode: () -> Void
    var filePreviewStore: AppStore? = nil
    var header = AnyView(EmptyView())
    var safeArea = EdgeInsets()
    var drawerPan = AnyView(EmptyView())
    var scrollEnabled = true
    @Environment(\.dynamicTypeSize) private var dynamicTypeSize
    @State private var showsSchedules = false
    @State private var showsRoster = false
    @State private var openedChat: String?
    @State private var selectedRole: BotRoleSelection?
    @State private var chatSearch = ""
    @State private var searchFocused = false
    @AppStorage(AppFontScale.key) private var fontScale = 1.0
    @AppStorage(AppFontScale.followsSystemKey) private var fontFollowsSystem = false
    private let cardSecondary = Color("BotSecondary")
    private var cardAccent: Color {
        colorScheme == .dark ? Color("BotPurple") : Color(red: 88.0 / 255, green: 65.0 / 255, blue: 144.0 / 255)
    }
    private var chief: BotChat? { model.snapshot.chats.first { $0.id == model.snapshot.mainBotId } }
    private var running: [BotChat] { model.snapshot.chats.filter(\.running) }
    private var openedChatExists: Bool { openedChat.map { id in model.snapshot.chats.contains { $0.id == id } } ?? true }

    var body: some View {
        GeometryReader { geometry in
            let wide = geometry.size.width >= 760 && !dynamicTypeSize.isAccessibilitySize
                && (geometry.size.height >= 500 || searchFocused)
                && AppFontScale.effective(fontScale, followsSystem: fontFollowsSystem) < 1.5
            if wide {
                ScrollView {
                    VStack(alignment: .leading, spacing: 40) {
                        header
                        HStack(alignment: .top, spacing: 48) {
                            assistantContent(wide: true).frame(width: min(440, geometry.size.width * 0.38))
                            chatSection(wide: true).frame(maxWidth: .infinity, alignment: .topLeading)
                        }
                    }
                    .padding(.horizontal, 40).padding(.top, safeArea.top + 18)
                    .padding(.bottom, safeArea.bottom + 24)
                    .readableContentWidth(AdaptiveLayout.workspaceWidth)
                    .background(drawerPan)
                }
                .scrollDisabled(!scrollEnabled).scrollIndicators(.hidden)
                .scrollDismissesKeyboard(.interactively)
                .accessibilityIdentifier("bot.wide-home")
            } else { compactHome }
        }
        .foregroundStyle(Color("BotInk"))
        .toolbar(.hidden, for: .navigationBar)
        .navigationDestination(isPresented: Binding(get: { openedChat != nil }, set: { shown in
            if !shown {
                openedChat = nil
                model.select(nil)
            }
        })) {
            if let id = openedChat { BotPrivateChatView(model: model, chatID: id, filePreviewStore: filePreviewStore) }
        }
        .onChangeCompat(of: openedChatExists) { _, exists in
            if !exists { openedChat = nil; model.select(nil) }
        }
        .sheet(isPresented: $showsSchedules) { BotScheduleSheet(model: model) }
        .sheet(item: $selectedRole) { role in BotRoleSheet(model: model, id: role.id) }
        .navigationDestination(isPresented: $showsRoster) { BotRosterView(model: model) }
        .task {
            model.setForeground(scenePhase == .active)
            model.activate()
        }
        .onChangeCompat(of: scenePhase) { _, phase in model.setForeground(phase == .active) }
    }

    private func open(_ id: String) {
        searchFocused = false
        model.select(id)
        openedChat = id
    }

    private var compactHome: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                header
                Spacer(minLength: 44)
                assistantContent(wide: false)
                chatSection(wide: false)
            }.padding(.horizontal, 22).padding(.top, safeArea.top + 18)
                .padding(.bottom, safeArea.bottom + 16)
                .background(drawerPan)
        }
        .scrollDisabled(!scrollEnabled).scrollIndicators(.hidden)
        .scrollDismissesKeyboard(.interactively)
    }

    private func assistantContent(wide: Bool) -> some View {
        VStack(alignment: .leading, spacing: 16) {
            VStack(alignment: .leading, spacing: wide ? 6 : 3) {
                Text("个人助理").appFont(.system(size: 32, weight: .bold))
                Text("今天也交给我吧。").appFont(.system(size: 15)).foregroundStyle(.secondary)
                    .frame(minHeight: wide ? 21 : 0, alignment: .leading)
            }
            Button { if let chief { selectedRole = BotRoleSelection(id: chief.id) } } label: {
                HStack(spacing: 12) {
                    BotAvatar(chat: chief, size: 44, main: true)
                    VStack(alignment: .leading, spacing: 2) {
                        Text(chief?.name ?? String(localized: "个人助理")).appFont(.system(size: 17, weight: .semibold))
                        HStack(spacing: 4) {
                            Circle().fill(chief?.running == true ? Color.green : Color("BotPurple")).frame(width: 5, height: 5)
                            Text(chief?.running == true ? String(format: String(localized: "正在为你推进 %lld 件事"), running.count) : String(localized: "随时可以找我聊聊"))
                                .appFont(.system(size: 12)).foregroundStyle(cardAccent)
                        }
                    }.frame(maxWidth: .infinity, alignment: .leading)
                }.padding(.horizontal, 16).padding(.vertical, 11).frame(maxWidth: .infinity, minHeight: 66, alignment: .leading)
                    .botHomeGlass(radius: 22)
            }.buttonStyle(.plain).disabled(chief == nil).accessibilityIdentifier("bot.chief")
            let chiefIndicator = chief.flatMap { model.snapshot.chatIndicator(chatId: $0.id) }
            Button { if let chief { open(chief.id) } } label: {
                HStack(spacing: 10) {
                    Image("BotConversationMark").renderingMode(.template).resizable().frame(width: 25.2422, height: 20.1094)
                    Text(chief.map { String(format: String(localized: "与 %@ 聊聊"), $0.name) } ?? String(localized: "与助理聊聊"))
                }
                .appFont(.system(size: 17, weight: .semibold))
                .padding(.horizontal, chiefIndicator != nil ? 64 : 0)
                .frame(maxWidth: .infinity, minHeight: 52)
                .overlay(alignment: .trailing) {
                    if let chief, let chiefIndicator {
                        BotChatStatusMark(chatID: chief.id, indicator: chiefIndicator)
                            .padding(.trailing, 16)
                    }
                }
                .botHomeGlass(radius: 26)
            }.buttonStyle(.plain).disabled(chief == nil).accessibilityIdentifier("bot.start-chat")
            if !model.snapshot.connected || !model.snapshot.supported || model.snapshot.error != nil {
                VStack(alignment: .leading, spacing: 8) {
                    Text(!model.snapshot.connected ? String(localized: "连接主机后查看个人助理") : !model.snapshot.supported ? String(localized: "请更新主机上的移动网关以使用 Bot 模式") : botErrorText(model.snapshot.error ?? ""))
                        .appFont(.system(size: 15)).foregroundStyle(cardSecondary)
                    if model.snapshot.connected && model.snapshot.supported { Button("重新同步") { model.refresh() }.tint(Color("BotPurple")) }
                }.padding(16).botHomeGlass()
            }
            if model.snapshot.loading && model.snapshot.chats.isEmpty { ProgressView("正在同步助理").frame(maxWidth: .infinity) }
            HStack(spacing: 12) {
                shortcut(LocalizedStringKey("我的 Bot"), count: model.snapshot.chats.filter { !$0.room }.count,
                    subtitle: String(localized: "查看与创建")) { showsRoster = true }
                    .accessibilityIdentifier("bot.roster")
                shortcut(LocalizedStringKey("定时任务"), count: model.snapshot.schedules.count,
                    subtitle: model.snapshot.schedules.first.map { String(format: String(localized: "下次 %@"), $0.next) } ?? String(localized: "查看安排")) { showsSchedules = true }
                    .accessibilityIdentifier("bot.schedules")
            }
        }
    }

    private func chatSection(wide: Bool) -> some View {
        let term = chatSearch.trimmingCharacters(in: .whitespacesAndNewlines)
        let chats = model.searchChats(term)
        return VStack(spacing: wide ? 16 : 10) {
            sectionTitle(LocalizedStringKey("聊天"), trailing: !term.isEmpty
                ? String(format: String(localized: "%lld 个结果"), chats.count) : String(localized: "群聊与私聊"))
                .frame(minHeight: wide ? 22 : 0)
            BotChatSearchField(text: $chatSearch, focused: $searchFocused)
                .frame(height: 44)
            VStack(spacing: 0) {
                if chats.isEmpty {
                    if !term.isEmpty {
                        VStack(spacing: 8) {
                            Text("没有找到相关聊天").appFont(.system(size: 17, weight: .semibold))
