                        }.frame(maxWidth: .infinity, minHeight: 138).padding(16)
                            .accessibilityIdentifier("bot.search-empty")
                    } else {
                        Text("还没有可用的 Bot，请先在主机上配置助理").appFont(.system(size: 15)).foregroundStyle(cardSecondary)
                            .frame(maxWidth: .infinity, alignment: .leading).padding(16)
                    }
                }
                ForEach(Array(chats.enumerated()), id: \.element.id) { index, chat in
                    Button { open(chat.id) } label: {
                        HStack(spacing: 12) {
                            BotAvatar(chat: chat, roster: model.snapshot.chats, size: 48,
                                      main: chat.id == model.snapshot.mainBotId)
                            VStack(alignment: .leading, spacing: 4) {
                                Text(chat.name).appFont(.system(size: 17, weight: .semibold)).lineLimit(1)
                                Text(chat.preview.isEmpty ? (chat.room ? String(localized: "群聊") : chat.role) : chat.preview)
                                    .appFont(.system(size: 15)).foregroundStyle(cardSecondary).lineLimit(1)
                            }.frame(maxWidth: .infinity, alignment: .leading)
                            let indicator = model.snapshot.chatIndicator(chatId: chat.id)
                            if chat.lastAt > 0 || indicator != nil {
                                VStack(alignment: .leading, spacing: 6) {
                                    if chat.lastAt > 0 {
                                        Text(Date(timeIntervalSince1970: chat.lastAt / 1000), style: .time)
                                            .appFont(.system(size: 11)).foregroundStyle(cardSecondary)
