    private func sectionTitle(_ title: LocalizedStringKey, trailing: String) -> some View {
        HStack { Text(title).appFont(.system(size: 17, weight: .semibold)); Spacer(); Text(trailing).appFont(.system(size: 12)).foregroundStyle(.secondary) }
    }
    private func shortcut(_ title: LocalizedStringKey, count: Int, subtitle: String, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            VStack(alignment: .leading, spacing: 3) {
