/// 使用系统搜索控件，保留原生清除、选区、键盘与无障碍行为。
private struct BotChatSearchField: UIViewRepresentable {
    @Environment(\.colorScheme) private var colorScheme
    @Binding var text: String
    @Binding var focused: Bool

    func makeUIView(context: Context) -> UISearchTextField {
        let field = UISearchTextField()
        field.placeholder = String(localized: "搜索聊天名称或内容")
        field.accessibilityIdentifier = "bot.chat-search"
        field.autocapitalizationType = .none
        field.autocorrectionType = .no
        field.returnKeyType = .search
        field.delegate = context.coordinator
        field.setContentHuggingPriority(.defaultLow, for: .horizontal)
        field.addTarget(context.coordinator, action: #selector(Coordinator.changed(_:)), for: .editingChanged)
        return field
    }

    func updateUIView(_ field: UISearchTextField, context: Context) {
        context.coordinator.parent = self
        if field.text != text { field.text = text }
        field.font = .appPreferredFont(forTextStyle: .body)
        field.textColor = UIColor(named: "BotInk")
        field.tintColor = UIColor(named: "BotPurple")
        field.layer.cornerRadius = 13
        field.clipsToBounds = true
        if colorScheme == .dark {
            let tint = UIColor(named: "BotSecondary")
            field.backgroundColor = UIColor(named: "BotGlassTint")
            field.layer.borderWidth = 0.8
            field.layer.borderColor = UIColor(named: "BotGlassRim")?.resolvedColor(with: field.traitCollection).cgColor
            field.attributedPlaceholder = NSAttributedString(string: String(localized: "搜索聊天名称或内容"),
                attributes: [.foregroundColor: tint ?? UIColor.secondaryLabel])
            (field.leftView as? UIImageView)?.tintColor = tint
        } else {
            field.backgroundColor = UIColor(named: "BotPurple")?.withAlphaComponent(0.28)
            field.layer.borderWidth = 0
            let ink = UIColor(named: "BotInk")?.withAlphaComponent(0.8) ?? UIColor.secondaryLabel
            field.attributedPlaceholder = NSAttributedString(string: String(localized: "搜索聊天名称或内容"),
                attributes: [.foregroundColor: ink])
            (field.leftView as? UIImageView)?.tintColor = ink
        }
        if !focused && field.isFirstResponder { field.resignFirstResponder() }
    }

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    final class Coordinator: NSObject, UITextFieldDelegate {
        var parent: BotChatSearchField
        init(_ parent: BotChatSearchField) { self.parent = parent }
        @objc func changed(_ field: UITextField) { parent.text = field.text ?? "" }
        func textFieldDidBeginEditing(_ textField: UITextField) { parent.focused = true }
        func textFieldDidEndEditing(_ textField: UITextField) { parent.focused = false }
        func textFieldShouldReturn(_ textField: UITextField) -> Bool { textField.resignFirstResponder(); return true }
    }
}

