struct BotAvatar: View {
    @Environment(\.colorScheme) private var colorScheme
    let chat: BotChat?
    var roster: [BotChat] = []
    var size: CGFloat = 28
    var main = false

    var body: some View {
        let members = chat?.room == true
            ? chat?.memberIds.compactMap { id in roster.first { $0.id == id } } ?? [] : []
        let seats = BotAvatarLayout.shared.seats(memberCount: Int32(members.count))
        Group {
            if !seats.isEmpty {
                ZStack(alignment: .topLeading) {
                    ForEach(seats.indices, id: \.self) { index in
                        let seat = seats[index]
                        let side = size * seat.side
                        Group {
                            if index == 3 && members.count > 4 {
                                Text("+\(members.count - 3)").appFont(.system(size: side * 0.36, weight: .semibold))
                            } else {
                                BotFace(chat: members[index], size: side)
                            }
                        }
                        .frame(width: side, height: side)
                        .background(Color("BotLavenderSoft"))
                        .clipShape(Circle())
                        .overlay { Circle().strokeBorder(colorScheme == .dark ? Color("BotLine") : .white, lineWidth: 1) }
                        .offset(x: size * seat.x, y: size * seat.y)
                    }
                }.frame(width: size, height: size, alignment: .topLeading)
            } else {
                BotFace(chat: members.first ?? chat, size: size, main: main)
            }
        }.accessibilityHidden(true)
    }
}

struct BotFace: View {
    let chat: BotChat?
    let size: CGFloat
    var main = false
    @State private var loaded: (request: PluginIconImageCache.Request, image: UIImage)?
    @Environment(\.colorScheme) private var colorScheme

    var body: some View {
        let request = chat?.image.map { PluginIconImageCache.Request(dataURL: $0, isDark: colorScheme == .dark) }
        let cached = request.flatMap { PluginIconImageCache.shared.cachedImage(for: $0) }
        let rendered = cached ?? (loaded?.request == request ? loaded?.image : nil)
        Group {
            if let rendered {
                Image(uiImage: rendered).resizable().scaledToFit()
            } else if chat?.room == true {
                Image("BotGroupAvatar").resizable().scaledToFit()
            } else if main {
                WhalenessOrcaIcon(size: size * 0.58).foregroundStyle(Color("BotInk"))
            } else {
                Text(String(chat?.name.prefix(1) ?? ""))
                    .font(.system(size: size * 0.42, weight: .semibold)).foregroundStyle(Color("BotBlue"))
            }
        }.frame(width: size, height: size).clipShape(RoundedRectangle(cornerRadius: size / 3))
            .task(id: rendered == nil ? request : nil) {
                guard let request, rendered == nil,
                      let image = await PluginIconImageCache.shared.image(for: request),
                      !Task.isCancelled else { return }
                loaded = (request, image)
            }
    }
}

private struct BotPrivateChatView: View {
    @Environment(\.colorScheme) private var colorScheme
    @ObservedObject var model: BotModeModel
    let chatID: String
    var filePreviewStore: AppStore? = nil
    var embedded = false
    @Environment(\.dismiss) private var dismiss
    @State private var mentionDraft = BotMentions.shared.emptyDraft()
    @State private var selection = NSRange(location: 0, length: 0)
    @State private var selectionRequest: ComposerSelectionRequest?
    @State private var question: BotQuestionSelection?
    @State private var showsSchedules = false
    @State private var viewportProxy = ConversationViewportProxy()
    @State private var viewportTimeline = ConversationTimeline()
    @State private var hasPresentedHistory = false
    @State private var scrollToBottomRequest = 0
    @State private var isPinnedToBottom = true
    @State private var bottomSafeAreaInset: CGFloat = 0
    @State private var additionalKeyboardInset: CGFloat = 0
    @State private var role: BotRoleSelection?
    @State private var showsMembers = false
    @State private var focused = false
    @State private var photos: [PhotosPickerItem] = []
    @State private var importingPhotos = false
    @State private var pickedImages: [GatewayOutgoingImage] = []
    @State private var showPhotos = false
    @State private var showFiles = false
    @State private var fileTarget: String?
    @State private var inputError: String?
    @State private var inputHeight: CGFloat = 74
    @State private var submittedAttachment: String?
    private var conversationSurface: Color { colorScheme == .dark ? Color("BotLavender") : Color(uiColor: .systemBackground) }
    private let maxImages = 4
    private let maxImageBytes = 12 * 1024 * 1024
    private var imageRoom: Int { min(maxImages - pickedImages.count, 20 - pickedImages.count - model.uploads.drafts.count) }
    private var draft: String { mentionDraft.text }
    private var mentionTrigger: BotMentionTrigger? {
        guard focused, selection.length == 0, let cursor = Int32(exactly: selection.location), !model.snapshot.attachmentSending else { return nil }
        return mentionDraft.trigger(cursor: cursor)
    }
    private var referenceSearchKey: String? {
        guard model.snapshot.referencesSupported, let trigger = mentionTrigger else { return nil }
        return chatID + (trigger.quoted ? ":quoted:" : ":") + trigger.query
    }
    private var hasDraft: Bool {
        mentionDraft.hasQuotes() || !draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ||
            !pickedImages.isEmpty || !model.uploads.drafts.isEmpty
    }
    private var chat: BotChat? { model.snapshot.chats.first { $0.id == chatID } }
    private var isChief: Bool { chatID == model.snapshot.mainBotId }
    private var composerPlaceholder: String {
        guard colorScheme == .dark, let chat else { return String(localized: "描述你想要构建的内容") }
        return chat.room ? String(localized: "发消息到群聊…")
            : String(format: String(localized: "发消息给 %@…"), chat.name)
    }

    var body: some View {
        conversationNavigation
            .onAppear { if model.snapshot.selectedChatId != chatID { model.select(chatID) } }
            .onChangeCompat(of: chatID) { _, id in
                hasPresentedHistory = false
                isPinnedToBottom = true
                model.select(id)
            }
            .onChangeCompat(of: model.snapshot.lastAttachmentAck) { _, ack in
                if let ack, ack == submittedAttachment {
                    mentionDraft = BotMentions.shared.emptyDraft()
                    pickedImages = []
                    focused = false
                    submittedAttachment = nil
                }
            }
            .task(id: referenceSearchKey) {
                guard referenceSearchKey != nil, let trigger = mentionTrigger else { model.clearReferenceSearch(); return }
                do { try await Task.sleep(for: .milliseconds(180)) } catch { return }
                model.searchReferences(trigger.query, quoted: trigger.quoted)
            }
            .sheet(item: $question) { selection in
                BotQuestionSheet(question: selection.value) { selected, custom in
                    model.answer(selection.value, selected: selected, custom: custom)
                    question = nil
                }
            }
            .sheet(isPresented: $showsSchedules) { BotScheduleSheet(model: model) }
            .sheet(item: $role) { selected in BotRoleSheet(model: model, id: selected.id) }
            .sheet(isPresented: $showsMembers) {
                BotMemberSheet(model: model, memberIDs: chat?.memberIds ?? [])
            }
            .modifier(BotFilePreviewPresentation(store: filePreviewStore, chatID: chatID))
            .alert("添加附件", isPresented: attachmentErrorPresented) {
                Button("好", role: .cancel) {}
            } message: {
                Text(inputError ?? model.attachmentError ?? "")
            }
    }

    private var attachmentErrorPresented: Binding<Bool> {
        Binding(
            get: { inputError != nil || model.attachmentError != nil },
            set: { presented in
                if !presented {
                    inputError = nil
                    model.clearAttachmentError()
                }
            }
        )
    }

    private func conversationLayout(topInset: CGFloat) -> some View {
        GeometryReader { geometry in
            let extraInset = min(additionalKeyboardInset, max(0, geometry.size.height - 1))
            ZStack(alignment: .bottom) {
                VStack(spacing: 0) {
                    if embedded { HStack { identity; Spacer(); moreButton }.padding(.horizontal, 16).frame(minHeight: 66) }
                    timeline(topInset: topInset)
                }
                ConversationComposerChrome(background: conversationSurface, contentHeight: $inputHeight,
                    showsJump: hasPresentedHistory && !model.snapshot.messages.isEmpty && !isPinnedToBottom,
                    isGenerating: chat?.running == true, onJump: { scrollToBottomRequest &+= 1 }) {
                        EmptyView()
                    } content: {
                        composer
                    }.zIndex(2)
            }
            .padding(.bottom, extraInset)
        }
        .background(conversationSurface.ignoresSafeArea())
        .ignoresSafeArea(.container, edges: .bottom)
        .background {
            WindowBottomSafeAreaReader(bottomInset: $bottomSafeAreaInset, keyboardInset: $additionalKeyboardInset)
                .ignoresSafeArea(.container, edges: .bottom)
        }
        .overlay(alignment: .top) {
            if #unavailable(iOS 26.0), embedded || topInset > 0 {
                ConversationTopGlass()
                    .frame(height: embedded ? 12 : topInset + 32)
                    .allowsHitTesting(false)
                    .accessibilityHidden(true)
            }
        }
        .foregroundStyle(.primary)
    }

    private var conversationNavigation: some View {
        Group {
            if embedded {
                conversationLayout(topInset: 0)
            } else {
                ConversationTopSafeArea { topInset in
                    conversationLayout(topInset: topInset)
                }
            }
        }
            .toolbar(embedded ? .hidden : .visible, for: .navigationBar)
            .navigationBarTitleDisplayMode(.inline)
            .toolbarRole(.editor)
            .toolbarBackground(.hidden, for: .navigationBar)
            .modifier(ConversationScrollEdgeStyle())
            .toolbar {
                if !embedded {
                    ToolbarItem(placement: .principal) {
                        identity.frame(maxWidth: 220).fixedSize(horizontal: false, vertical: true)
                    }
                    if #available(iOS 26.0, *) {
                        ToolbarItem(placement: .topBarTrailing) { moreButton }.sharedBackgroundVisibility(.hidden)
                    } else {
                        ToolbarItem(placement: .topBarTrailing) { moreButton }
                    }
                }
            }
            .tint(.primary)
    }

    private func timeline(topInset: CGFloat) -> some View {
        let snapshot = model.snapshot
        let messages = snapshot.selectedChatId == chatID ? snapshot.messages : []
        let interactions = snapshot.interactions.filter { $0.chatId == chatID }
        let liveWork = snapshot.visibleLiveWork(chatId: chatID)
        let canLoadEarlier = !snapshot.historyLoading && snapshot.connected && snapshot.supported
        let historyControls: [ConversationViewportEntry]
        if snapshot.selectedChatId == chatID && snapshot.hasEarlier {
            historyControls = [ConversationViewportEntry(id: "bot-load-earlier", revision: canLoadEarlier ? 1 : 0,
                content: AnyView(Button("加载更早消息") { model.loadEarlier() }
                    .disabled(!canLoadEarlier).frame(maxWidth: .infinity).padding(.bottom, 18)))]
        } else {
            historyControls = []
        }

        return ConversationViewport(
            proxy: viewportProxy,
            sessionID: chatID,
            cacheScope: model.viewportCacheScope,
            timeline: viewportTimeline,
            supplementalEntries: historyControls,
            makeEntries: { _ in historyEntries(snapshot: snapshot, messages: messages, interactions: interactions, liveWork: liveWork) },
            projectedRevision: model.viewportRevision,
            hasProjectedConversationContent: !messages.isEmpty || !interactions.isEmpty || !historyControls.isEmpty || liveWork != nil,
            topInset: topInset + 18,
            bottomInset: inputHeight + ConversationComposerChromeMetrics.bottomClearance,
            scrollToBottomToken: scrollToBottomRequest,
            onContentAvailabilityChanged: { id, available in
                Task { @MainActor in
                    if id == chatID { hasPresentedHistory = available }
                }
            },
            onPinnedToBottomChanged: { pinned in
                Task { @MainActor in isPinnedToBottom = pinned }
            },
            onScrolledFromTopChanged: { _ in },
            onBottomAlignmentCompleted: {},
            onApproachingTop: {}
        )
        .id(chatID)
        .overlay(alignment: .top) {
            if snapshot.historyLoading && messages.isEmpty && interactions.isEmpty {
                ProgressView("正在读取聊天").padding(.top, topInset + 18)
            }
        }
        .onChangeCompat(of: focused) { _, isFocused in
            if isFocused { scrollToBottomRequest &+= 1 }
        }
        .onChangeCompat(of: messages.last?.id) { _, _ in
            if messages.last?.delivery == "sending" { scrollToBottomRequest &+= 1 }
        }
        .task(id: messages.first?.id) {
            let candidates = messages.suffix(24) + messages.dropLast(24).prefix(12)
            let sources = candidates.compactMap { message -> String? in
                if message.streaming || message.text.isEmpty ||
                    message.kind == "user" || message.kind == "event" || message.kind == "divider" { return nil }
                return message.text
            }
            await withTaskGroup(of: Void.self) { group in
                group.addTask(priority: .utility) {
                    for source in sources {
                        guard !Task.isCancelled else { return }
                        _ = PreparedMarkdownCache.document(for: source, filePaths: [])
                    }
                }
            }
        }
    }

    private func historyEntries(snapshot: SharedBotSnapshot, messages: [BotChatMessage],
                                interactions: [BotInteraction], liveWork: BotLiveWork?) -> [ConversationViewportEntry] {
        let roster = Dictionary(snapshot.chats.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
        let palette = BotBubblePalette(chats: snapshot.chats, mainBotId: snapshot.mainBotId)
        let conversation = roster[chatID]
        let room = conversation?.room == true
        let fallback = room ? nil : conversation
        let deliveredBySession = Dictionary(grouping: messages.filter { !$0.sessionId.isEmpty && !$0.files.isEmpty },
                                            by: \.sessionId).mapValues { messages in
            let paths = Set(messages.flatMap { $0.files.map(\.path) })
            return paths.sorted().map { PresentedFile(path: $0) }
        }
        let rows = messages.map { message in
            let author = message.botId.flatMap { roster[$0] } ?? (message.activity == nil ? fallback : nil)
            let main = author?.id == snapshot.mainBotId
            let bubbleRGB = palette.rgb(botId: message.botId ?? author?.id, dark: colorScheme == .dark)
            let containsInlineCode = message.text.contains("`") || message.quoteParts.contains { $0.type == "text" && $0.text.contains("`") }
            let knownFiles = containsInlineCode ? deliveredBySession[message.sessionId, default: []] : []
            var revision = Hasher()
            revision.combine(message.hash)
            revision.combine(author?.id)
            revision.combine(author?.name)
            revision.combine(author?.image)
            revision.combine(author?.room)
            revision.combine(room)
            revision.combine(main)
            revision.combine(bubbleRGB)
            revision.combine(knownFiles)
            return ConversationViewportEntry(id: "bot-message-" + message.id, revision: revision.finalize(),
                content: AnyView(BotMessageRow(message: message, author: author, room: room, main: main, bubbleRGB: bubbleRGB,
                    chatID: chatID, model: model, knownFiles: knownFiles, onReply: quoteMessage, onShowProfile: { id in
                        viewportProxy.prepareForOverlayPresentation()
                        role = BotRoleSelection(id: id)
                    }, onOpenFile: { path in
                        // SwiftUI 的链接回调可能在视图更新期间触发。
                        Task { @MainActor in
                            focused = false
                            viewportProxy.prepareForOverlayPresentation()
                            filePreviewStore?.openBotFile(chatID: chatID, messageID: message.id, path: path)
                        }
                    }).frame(maxWidth: 748).frame(maxWidth: .infinity).padding(.bottom, 18)),
                allowsHeightCaching: !message.streaming,
                layoutRevision: knownFiles.isEmpty ? message.hash : message.hash ^ knownFiles.hashValue,
                preservesContentIdentity: true)
        }
        let interactionRows = interactions.map { interaction in
            ConversationViewportEntry(id: "bot-interaction-" + interaction.id, revision: interaction.hash,
                content: AnyView(interactionRow(interaction)))
        }
        guard let liveWork else { return rows + interactionRows }
        let author = liveWork.botId.flatMap { roster[$0] } ?? conversation
        var revision = Hasher()
        revision.combine(liveWork.hash)
        revision.combine(author?.hash)
        revision.combine(author?.memberIds.compactMap { roster[$0]?.image })
        let status = BotLiveWorkRow(work: liveWork, author: author, roster: snapshot.chats,
                                    main: author?.id == snapshot.mainBotId)
        return rows + interactionRows + [
            ConversationViewportEntry(id: "bot-live-work", revision: revision.finalize(),
                content: AnyView(status.frame(maxWidth: 748).frame(maxWidth: .infinity).padding(.bottom, 18)),
                preservesContentIdentity: true)
        ]
    }

    private func interactionRow(_ interaction: BotInteraction) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(interaction.kind == "approval" ? String(localized: "需要你批准") : String(localized: "助理在等你回答"))
                .appFont(.system(size: 12)).foregroundStyle(.secondary)
            Text(interaction.title).appFont(.system(size: 17, weight: .semibold))
            if !interaction.detail.isEmpty {
                Text(interaction.detail).appFont(.system(size: 15)).foregroundStyle(.secondary)
            }
            if interaction.kind == "approval" {
                HStack {
                    Button("拒绝", role: .destructive) { model.approve(interaction.id, allow: false) }
                    Spacer()
                    Button("仅允许这一次") { model.approve(interaction.id, allow: true) }
                }
            } else {
                Button("回答") { question = BotQuestionSelection(value: interaction) }
            }
        }
        .botContentCard().frame(maxWidth: 748, alignment: .leading).frame(maxWidth: .infinity).padding(.bottom, 18)
    }

    private var identity: some View {
        Button {
            guard let chat else { return }
            focused = false
            if chat.room { showsMembers = true }
            else { role = BotRoleSelection(id: chat.id) }
        } label: {
        HStack(spacing: 10) {
            BotAvatar(chat: chat, roster: model.snapshot.chats, size: 36, main: isChief)
            VStack(alignment: .leading, spacing: 2) {
                Text(chat?.name ?? String(localized: "个人助理")).appFont(.system(size: 17, weight: .semibold)).lineLimit(1)
                Text(chat?.room == true ? String(localized: "群聊") : (chat?.role.isEmpty == false ? chat!.role : String(localized: "随时为你效劳")))
                    .appFont(.system(size: 12)).foregroundStyle(.secondary).lineLimit(1)
            }
        }.accessibilityElement(children: .combine)
        }.buttonStyle(.plain).disabled(chat == nil).accessibilityIdentifier("bot.chat-identity")
    }
    private var moreButton: some View {
        BotChatMoreButton(refresh: model.refresh, schedules: { showsSchedules = true })
            .frame(width: 44, height: 44)
    }
    private var composer: some View {
        VStack(spacing: 6) {
            if let trigger = mentionTrigger {
                let matching = model.snapshot.referenceSearch.flatMap { search in
                    search.chatId == chatID && search.query == trigger.query && search.quoted == trigger.quoted ? search : nil
                }
                let members = trigger.quoted || trigger.query.contains("/") ? [] :
                    BotMentions.shared.members(chatId: chatID, chats: model.snapshot.chats, query: trigger.query)
                BotMentionMenu(model: model, candidates: members + (matching?.items ?? []),
                    loading: model.snapshot.referencesSupported && model.snapshot.connected && (matching?.loading ?? true),
                    unavailable: matching?.unavailable == true,
                    pick: { candidate, label in updateMention(mentionDraft.insert(trigger: trigger, candidate: candidate, label: label)) },
                    drill: { path in updateMention(mentionDraft.drill(trigger: trigger, path: path)) })
            }
            if let error = model.snapshot.error { Text(botErrorText(error)).appFont(.caption).foregroundStyle(.secondary) }
            ComposerQuoteStack(parts: mentionDraft.quoteParts().map { GatewayTextPart(type: $0.type, text: $0.text) },
                visible: focused || hasDraft, onRemove: { index in
                    guard !model.snapshot.attachmentSending else { return }
                    mentionDraft = mentionDraft.removeQuote(partIndex: Int32(index))
                }) {
                composerInput
            }.padding(.horizontal, 14).padding(.vertical, 8).composerGlassSurface(radius: 24,
                tint: colorScheme == .dark ? Color("BotGlassTint").opacity(0.84) : nil,
                edge: colorScheme == .dark ? Color("BotGlassRim").opacity(0.7) : nil)
        }.padding(.horizontal, 14)
            .padding(.bottom, ConversationComposerChromeMetrics.bottomPadding(safeAreaInset: bottomSafeAreaInset))
    }

    private var composerInput: some View {
        ComposerAttachmentStack(shown: focused || hasDraft,
            hasContent: !pickedImages.isEmpty || !model.uploads.drafts.isEmpty || model.uploads.preparing) {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(pickedImages) { source in
                        if let image = UIImage(data: source.data) {
                            Image(uiImage: image).resizable().scaledToFill().frame(width: 48, height: 48)
                                .clipShape(RoundedRectangle(cornerRadius: 10))
                                .overlay(alignment: .topTrailing) {
                                    Button { pickedImages.removeAll { $0.id == source.id } } label: {
                                        Image(systemName: "xmark.circle.fill").symbolRenderingMode(.palette)
                                            .foregroundStyle(.white, .black.opacity(0.75))
                                    }.buttonStyle(.plain).disabled(model.snapshot.attachmentSending).accessibilityLabel("移除")
                                }
                        }
                    }
                    ForEach(model.uploads.drafts, id: \.id) { file in
                        PendingFileCard(file: file, status: conversationUploadStatus(file),
                            enabled: !model.snapshot.attachmentSending, onRetry: { model.uploads.retry(file.id) },
                            onRemove: { model.uploads.remove(file.id) })
                    }
                    if model.uploads.preparing || importingPhotos { ProgressView() }
                }
            }
        } content: {
            ComposerMorphLayout(expansion: focused ? 1 : 0, keepActionWhenCollapsed: hasDraft || colorScheme == .dark) {
                Menu {
                    Button { showPhotos = true } label: { Label("图片", systemImage: "photo") }
                        .disabled(importingPhotos || imageRoom <= 0)
                    Button {
                        fileTarget = model.selectedSessionID
                        showFiles = true
                    } label: { Label("文件", systemImage: "doc") }
                        .disabled(!model.uploads.supported || model.uploads.preparing || pickedImages.count + model.uploads.drafts.count >= 20)
                } label: { ConversationAttachmentButtonLabel() }
                    .buttonStyle(.plain)
                    .disabled(!model.snapshot.connected || !model.snapshot.attachmentsSupported ||
                        !model.snapshot.writable || model.snapshot.attachmentSending)
                    .accessibilityLabel("添加附件")
                    .photosPicker(isPresented: $showPhotos, selection: $photos,
                        maxSelectionCount: max(1, imageRoom), matching: .images)
                    .fileImporter(isPresented: $showFiles, allowedContentTypes: [.item], allowsMultipleSelection: true) {
                        if case .success(let urls) = $0, urls.count + pickedImages.count + model.uploads.drafts.count > 20 {
                            inputError = String(localized: "一次最多添加 20 个附件，请等待已有附件准备完成")
                        } else { model.importFiles($0, target: fileTarget) }
                    }
                SlashCommandTextView(text: Binding(get: { mentionDraft.text }, set: { mentionDraft = mentionDraft.replacingText(value: $0) }),
                    presentation: nil, placeholder: composerPlaceholder, isFocused: $focused,
                    isCompact: !focused, onSelectionChange: { selection = $0 },
                    referenceRanges: mentionDraft.spans.map { NSRange(location: Int($0.start), length: Int($0.end - $0.start)) },
                    selectionRequest: selectionRequest)
                    .padding(.horizontal, 3).frame(minHeight: 38, alignment: .top)
                    .disabled(model.snapshot.attachmentSending).accessibilityIdentifier("bot.composer")
                Spacer(minLength: 0)
                ZStack {
                    if hasDraft || colorScheme == .dark {
                        Button {
                            let includesAttachments = !pickedImages.isEmpty || !model.uploads.drafts.isEmpty
                            guard let requestID = model.send(mentionDraft.wireText(), displayText: mentionDraft.displayText(),
                                images: pickedImages) else { return }
                            if includesAttachments { submittedAttachment = requestID }
                            else { mentionDraft = BotMentions.shared.emptyDraft() }
                            focused = false
                        } label: { ConversationComposerSendIcon(fill: colorScheme == .dark ? Color("BotSend") : DSHColor.ocean) }
                            .buttonStyle(.plain)
                            .disabled(!hasDraft || !model.snapshot.connected || !model.snapshot.writable || importingPhotos ||
                                model.uploads.preparing || model.snapshot.attachmentSending ||
                                (!model.uploads.drafts.isEmpty && !model.uploads.canSend))
                            .accessibilityLabel("发送消息")
                    }
                }.frame(width: 42, height: 42)
            }.animation(.easeOut(duration: 0.22), value: focused)
        }
        .onChange(of: photos) { items in
            guard !items.isEmpty else { return }
            let target = model.selectedSessionID
            Task {
                importingPhotos = true
                defer { importingPhotos = false; photos = [] }
                do {
                    var preparedImages: [GatewayOutgoingImage] = []
                    for item in items {
                        guard let data = try await item.loadTransferable(type: Data.self) else { continue }
                        let prepared = try await Task.detached { try GatewayImagePreprocessor.prepare(data: data) }.value
                        preparedImages.append(GatewayOutgoingImage(mediaType: prepared.mediaType, data: prepared.data))
                    }
                    guard target == model.selectedSessionID, !Task.isCancelled, preparedImages.count <= imageRoom else { return }
                    guard (pickedImages + preparedImages).reduce(0, { $0 + $1.data.count }) <= maxImageBytes else {
                        inputError = String(localized: "图片总大小超出限制")
                        return
                    }
                    pickedImages += preparedImages
                    if !preparedImages.isEmpty { focused = true }
                } catch { inputError = error.localizedDescription }
            }
        }
    }

    private func quoteMessage(_ text: String) {
        guard !model.snapshot.attachmentSending,
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let count = (draft as NSString).length
        let start = min(selection.location, count)
        let end = start + min(selection.length, count - start)
        updateMention(mentionDraft.insertQuote(quote: text, selectionStart: Int32(start), selectionEnd: Int32(end)))
        focused = true
    }
    private func updateMention(_ edit: BotMentionEdit) {
        mentionDraft = edit.draft
        selection = NSRange(location: Int(edit.cursor), length: 0)
        selectionRequest = ComposerSelectionRequest(range: selection)
    }
}

private struct BotFilePreviewPresentation: ViewModifier {
    let store: AppStore?
    let chatID: String

    func body(content: Content) -> some View {
        if let store { content.modifier(BotFilePreviewSheetHost(store: store, chatID: chatID)) }
        else { content }
    }
}

private struct BotFilePreviewSheetHost: ViewModifier {
    @ObservedObject var store: AppStore
    let chatID: String

    func body(content: Content) -> some View {
        content.sheet(item: Binding<WorkspaceFilePreviewRequest?>(
            get: {
                guard let request = store.workspaceFilePreviewRequest, request.botChatID == chatID else { return nil }
                return request
            },
            set: { if $0 == nil { cancel() } }
        )) { request in
            WorkspaceFilePreviewLoadingSheet(store: store, request: request)
        }
        .onDisappear(perform: cancel)
    }

    private func cancel() {
        if store.workspaceFilePreviewRequest?.botChatID == chatID { store.cancelWorkspaceFileDownload() }
    }
}

private struct BotMessageRow: View {
    @Environment(\.locale) private var locale
    @Environment(\.colorScheme) private var colorScheme
    let message: BotChatMessage
    let author: BotChat?
    let room: Bool
    let main: Bool
    let bubbleRGB: Int32
    let chatID: String
    let model: BotModeModel
    let knownFiles: [PresentedFile]
    let onReply: (String) -> Void
    let onShowProfile: (String) -> Void
    let onOpenFile: (String) -> Void

    private let avatarSize: CGFloat = 28
    private let avatarSpacing: CGFloat = 8
    private var agentContentInset: CGFloat { avatarSize + avatarSpacing }

    private var hasReplyAction: Bool {
        (message.kind == "bot" || message.kind == "post") && !message.streaming &&
            !message.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var time: String? {
        message.timeMs.map {
            ConversationTimeLabel.text(for: Date(timeIntervalSince1970: Double($0.int64Value) / 1_000),
                locale: locale, includesWeekday: true)
        }
    }

    var body: some View {
        if message.files.isEmpty {
            messageBody
        } else {
            VStack(alignment: .leading, spacing: 8) {
                if message.kind != "file", !message.text.isEmpty || !message.images.isEmpty { messageBody }
                ForEach(message.files, id: \.path) { file in
                    FileReferenceCard(path: file.path, description: file.description_) { onOpenFile(file.path) }
                        .padding(.leading, agentContentInset)
                }
                if hasReplyAction {
                    AssistantMessageActions(text: message.text, onReply: onReply)
                        .padding(.leading, agentContentInset)
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    @ViewBuilder private var messageBody: some View {
        let user = message.kind == "user"
        if let activity = message.activity {
            HStack(spacing: 6) {
                Text(activity == "bot-created" ? String(localized: "已创建") : String(localized: "已发消息给"))
                if let author { BotAvatar(chat: author, size: 18) }
                Text(author?.name ?? message.name)
            }
            .appFont(.footnote).foregroundStyle(.secondary)
            .frame(maxWidth: .infinity).accessibilityElement(children: .combine)
        } else if !message.questionAnswers.isEmpty {
            BotAnsweredQuestions(answers: message.questionAnswers)
        } else if message.kind == "event" || message.kind == "divider" {
            Text(message.text.isEmpty ? (message.kind == "divider" ? time : nil) ?? String(localized: "协作动态") : message.text)
                .appFont(.system(size: 12)).foregroundStyle(.secondary).frame(maxWidth: .infinity)
        } else {
            HStack(alignment: .top, spacing: avatarSpacing) {
                if user { Spacer(minLength: 40) }
                else {
                    Button {
                        if let author { onShowProfile(author.id) }
                    } label: {
                        BotAvatar(chat: author, size: avatarSize, main: main)
                            .accessibilityHidden(false)
                    }.buttonStyle(.plain).disabled(author == nil)
                        .accessibilityLabel(author?.name ?? String(localized: "个人助理"))
                }
                let images = message.images
                let imageContext = (!user || !images.isEmpty) ? model.imageContext(chatID: chatID, message: message) : nil
                VStack(alignment: user ? .trailing : .leading, spacing: 4) {
                    if room && !user && !message.name.isEmpty { Text(message.name).appFont(.system(size: 12)).foregroundStyle(.secondary) }
                    let parts = message.quoteParts
                    if !parts.isEmpty {
                        SentReplyBubble(textParts: parts.map { GatewayTextPart(type: $0.type, text: $0.text) },
                            knownFiles: knownFiles, onOpenFile: onOpenFile,
                            fill: colorScheme == .dark ? Color("BotUserBubble") : nil,
                            edge: colorScheme == .dark ? .clear : nil,
                            quoteFill: colorScheme == .dark ? Color("BotGlassTint") : nil)
                    }
                    if parts.isEmpty || !images.isEmpty {
                        chatBubble(user: user, includesText: parts.isEmpty, imageContext: imageContext)
                    }
                    if let time, message.kind == "user" || message.kind == "bot" || message.kind == "post" {
                        Text(time).appFont(.system(size: 11)).foregroundStyle(.secondary)
                            .accessibilityIdentifier("bot.message-time." + message.id)
                    }
                    if let delivery = message.delivery {
                        Text(delivery == "unknown" ? String(localized: "发送状态待确认，请同步聊天后核对") : delivery == "sending" ? String(localized: "发送中") : String(localized: "已发送"))
                            .appFont(.system(size: 11)).foregroundStyle(.secondary)
                    }
                    if hasReplyAction && message.files.isEmpty {
                        AssistantMessageActions(text: message.text, onReply: onReply)
                    }
                }.frame(maxWidth: 292, alignment: user ? .trailing : .leading)
                if !user { Spacer(minLength: 40) }
            }.frame(maxWidth: .infinity, alignment: user ? .trailing : .leading)
        }
    }

    private func chatBubble(user: Bool, includesText: Bool, imageContext: WorkspaceMarkdownImageContext?) -> some View {
        let isDark = colorScheme == .dark
        let bubble = RoundedRectangle(cornerRadius: 20)
        let agentFill = Color(.sRGB, red: Double((bubbleRGB >> 16) & 255) / 255,
            green: Double((bubbleRGB >> 8) & 255) / 255, blue: Double(bubbleRGB & 255) / 255)
        return VStack(alignment: .leading, spacing: 8) {
            if includesText {
                if user {
                    Text(message.text).appFont(.system(size: 17)).lineSpacing(4).textSelection(.enabled)
                } else if !message.text.isEmpty || message.images.isEmpty {
                    MarkdownContent(message.text.isEmpty ? String(localized: "交互卡片") : message.text,
                        knownFiles: knownFiles, onOpenFile: onOpenFile, textColor: Color("BotInk"))
                        .environment(\.workspaceMarkdownImageContext, imageContext)
                        .environment(\.messageQuoteAction, hasReplyAction ? onReply : nil)
                }
            }
            if let imageContext {
                ForEach(message.images, id: \.attachmentId) { ref in
                    MarkdownAttachmentImage(url: URL(fileURLWithPath: "/__bot_image__/" + ref.attachmentId), context: imageContext)
                        .accessibilityIdentifier("bot.image." + ref.attachmentId)
                }
            }
        }
        .padding(.horizontal, 14).padding(.vertical, 12)
        .background(user ? (isDark ? Color("BotUserBubble") : DSHColor.userBubbleFill(isDark: false)) : agentFill, in: bubble)
        .overlay {
            if user && !isDark { bubble.strokeBorder(DSHColor.userBubbleEdge(isDark: false), lineWidth: 0.7) }
        }
        .foregroundStyle(user ? Color.primary : Color("BotInk"))
    }
}

private struct BotAnsweredQuestions: View {
    let answers: [BotQuestionAnswer]

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            ForEach(answers.indices, id: \.self) { index in
                let answer = answers[index]
                VStack(alignment: .leading, spacing: 10) {
                    Text(answer.question).appFont(.system(size: 15, weight: .semibold)).foregroundStyle(.secondary)
                    ForEach(answer.choices.indices, id: \.self) { choiceIndex in
                        let choice = answer.choices[choiceIndex]
                        HStack(spacing: 10) {
                            if let letter = choice.letter {
                                Text(letter).appFont(.system(size: 13, weight: .semibold))
                                    .foregroundStyle(Color("BotBlue"))
                                    .padding(.horizontal, 8).padding(.vertical, 5)
                                    .background(Color("BotBlue").opacity(0.12), in: RoundedRectangle(cornerRadius: 7))
                            }
                            Text(choice.label).appFont(.system(size: 16)).foregroundStyle(Color("BotInk"))
                        }
                        .accessibilityElement(children: .combine)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .botContentCard(vertical: 12)
                .overlay { RoundedRectangle(cornerRadius: 20).strokeBorder(Color("BotLavenderSoft")) }
            }
        }
        .frame(maxWidth: 360, alignment: .leading)
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

private struct BotMentionMenu: View {
    @ObservedObject var model: BotModeModel
    let candidates: [BotMentionCandidate]
    let loading: Bool
    let unavailable: Bool
    let pick: (BotMentionCandidate, String) -> Void
    let drill: (String) -> Void

    private var groups: [(String, [BotMentionCandidate])] {
        [
            (String(localized: "成员"), candidates.filter { $0.kind == "member" || $0.kind == "everyone" }),
            (String(localized: "文件与文件夹"), candidates.filter { $0.kind == "file" || $0.kind == "directory" }),
            (String(localized: "对话"), candidates.filter { $0.kind == "session" })
        ].filter { !$0.1.isEmpty }
    }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 4) {
                ForEach(Array(groups.enumerated()), id: \.offset) { _, group in
                    Text(group.0).appFont(.caption).foregroundStyle(.secondary).padding(.horizontal, 12)
                    ForEach(group.1, id: \.self) { candidate in
                        let label = candidate.kind == "everyone" ? String(localized: "所有人") : candidate.label
                        HStack(spacing: 0) {
                            Button { pick(candidate, label) } label: {
                                HStack(spacing: 10) {
                                    candidateIcon(candidate)
                                    Text(label).appFont(.subheadline).lineLimit(1)
                                    Spacer(minLength: 4)
                                    if !candidate.detail.isEmpty {
                                        Text(candidate.detail).appFont(.caption).foregroundStyle(.secondary).lineLimit(1)
                                    }
                                }
                                .padding(.horizontal, 12).frame(minHeight: 42)
                                .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                            .accessibilityIdentifier("bot.mention." + candidate.kind + "." + candidate.id)
                            if let path = candidate.path, candidate.kind == "directory" {
                                Button { drill(path) } label: {
                                    Image(systemName: "chevron.right").frame(width: 44, height: 42)
                                }.buttonStyle(.plain).accessibilityLabel("展开文件夹")
                            }
                        }
                    }
                }
                if loading { ProgressView().frame(maxWidth: .infinity).padding(8) }
                else if candidates.isEmpty {
                    Text(unavailable ? String(localized: "暂时无法读取引用") : String(localized: "没有匹配的引用"))
                        .appFont(.subheadline).foregroundStyle(.secondary).padding(12)
                }
            }
            .padding(.vertical, 8)
        }
        .frame(height: min(220, CGFloat(16 + groups.count * 23 + candidates.count * 46 + (loading || candidates.isEmpty ? 48 : 0))))
        .composerGlassSurface(radius: 20)
        .accessibilityIdentifier("bot.mentions")
    }

    @ViewBuilder private func candidateIcon(_ candidate: BotMentionCandidate) -> some View {
        if candidate.kind == "member" {
            let chat = model.snapshot.chats.first { $0.id == candidate.id }
            BotAvatar(chat: chat, size: 22, main: candidate.id == model.snapshot.mainBotId)
        } else {
            let symbol = switch candidate.kind {
            case "everyone": "person.2"
            case "directory": "folder"
            case "session": "bubble.left"
            default: "doc"
            }
            Image(systemName: symbol).frame(width: 22)
        }
    }
}

// 使用 UIKit 的原生菜单，并固定按钮本身的测量尺寸。
private struct BotChatMoreButton: UIViewRepresentable {
    let refresh: () -> Void
    let schedules: () -> Void

    func makeUIView(context: Context) -> UIButton {
        let button = UIButton(type: .system)
        var configuration: UIButton.Configuration
        if #available(iOS 26.0, *) { configuration = .glass() }
        else {
            configuration = .plain()
            let blur = UIVisualEffectView(effect: UIBlurEffect(style: .systemThinMaterial))
            blur.frame = CGRect(x: 0, y: 0, width: 44, height: 44)
            blur.autoresizingMask = [.flexibleWidth, .flexibleHeight]
            blur.layer.cornerRadius = 22
            blur.clipsToBounds = true
            blur.isUserInteractionEnabled = false
            button.insertSubview(blur, at: 0)
        }
        configuration.image = UIImage(systemName: "ellipsis", withConfiguration: UIImage.SymbolConfiguration(pointSize: 19, weight: .semibold))
        configuration.cornerStyle = .capsule
        configuration.contentInsets = .zero
        configuration.baseForegroundColor = .label
        button.configuration = configuration
        button.showsMenuAsPrimaryAction = true
        button.accessibilityLabel = String(localized: "更多操作")
        button.accessibilityIdentifier = "bot.chat-more"
        return button
    }

    func updateUIView(_ button: UIButton, context: Context) {
        button.menu = UIMenu(children: [
            UIAction(title: String(localized: "重新同步"), image: UIImage(systemName: "arrow.clockwise")) { _ in refresh() },
            UIAction(title: String(localized: "定时任务"), image: UIImage(systemName: "clock")) { _ in schedules() }
        ])
    }

    func sizeThatFits(_ proposal: ProposedViewSize, uiView: UIButton, context: Context) -> CGSize? {
        CGSize(width: 44, height: 44)
    }
}

private struct BotQuestionSelection: Identifiable {
    let value: BotInteraction
    var id: String { value.id }
}

private struct BotQuestionSheet: View {
    let question: BotInteraction
    let submit: ([String], String) -> Void
    @Environment(\.dismiss) private var dismiss
    @State private var selected = Set<String>()
    @State private var custom = ""
    var body: some View {
        NavigationStack {
            Form {
                Section { Text(question.title); if !question.detail.isEmpty { Text(question.detail).foregroundStyle(.secondary) } }
                Section {
                    ForEach(question.options, id: \.self) { option in
                        Button {
                            if selected.contains(option) { selected.remove(option) }
                            else if question.multiSelect { selected.insert(option) }
                            else { selected = [option]; custom = "" }
                        } label: {
                            HStack { Text(option).foregroundStyle(.primary); Spacer(); if selected.contains(option) { Image(systemName: "checkmark") } }
                        }
                    }
                    TextField("补充回答", text: $custom, axis: .vertical).lineLimit(2...6)
                }
            }
            .navigationTitle("回答助理").navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }
                ToolbarItem(placement: .confirmationAction) {
                    Button("提交") { submit(Array(selected), custom) }.disabled(selected.isEmpty && custom.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
    }
}

