/// 仅连接隔离验证主机；不读取或替换用户已有主机配置。
struct BotModeUITestHarness: View {
    @StateObject private var model: BotModeModel
    @State private var failure: String?
    init() {
        let client = GatewayClient(credentials: BotTestCredentials(), prepareTunnel: { _ in true }, tunnelForwarder: { _ in nil })
        client.credentialID = "bot-ui-test-\(UUID().uuidString)"
        _model = StateObject(wrappedValue: BotModeModel(gateway: client))
    }
    var body: some View {
        NavigationStack { BotModeView(model: model, onStandardMode: {}) }
            .overlay(alignment: .bottom) {
                if let status = failure ?? (model.snapshot.connected ? nil : model.testConnectionState) {
                    Text(status).font(.caption).accessibilityIdentifier("bot.test-connection").allowsHitTesting(false)
                }
            }
            .preferredColorScheme(ProcessInfo.processInfo.environment["DSH_BOT_UI_APPEARANCE"] == "dark" ? .dark : nil)
            .task {
                guard ProcessInfo.processInfo.environment["DSH_BOT_UI_TEST_URL"] == "http://127.0.0.1:3098",
                      let url = URL(string: "http://127.0.0.1:3098/mgw/pair") else { return }
                do {
                    var request = URLRequest(url: url)
                    request.httpMethod = "POST"
                    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
                    request.httpBody = Data("{}".utf8)
                    let (data, _) = try await URLSession.shared.data(for: request)
                    let response = try JSONDecoder().decode(BotTestPairing.self, from: data)
                    try model.pairForUITest(response.qrPayload)
                } catch { failure = error.localizedDescription }
            }
    }
    private struct BotTestPairing: Decodable { let qrPayload: String }
}

private actor BotTestCredentials: GatewayCredentialStoring {
    private var tokens: [URL: String] = [:]
    private let deviceID = UUID().uuidString
    func loadToken(for endpoint: URL) -> String? { tokens[endpoint] }
    func saveToken(_ token: String, for endpoint: URL) { tokens[endpoint] = token }
    func deleteToken(for endpoint: URL) { tokens.removeValue(forKey: endpoint) }
    func loadOrCreateDeviceID() -> String { deviceID }
}
