private struct BotLiveWorkRow: View {
    let work: BotLiveWork
    let author: BotChat?
    let roster: [BotChat]
    let main: Bool
    @State private var observedAt = Date()

    private var title: String {
        switch work.kind {
        case "web-search": return String(localized: "上网搜索…")
        case "web-read": return String(localized: "正在浏览网页…")
        case "image": return String(localized: "正在生成图片…")
        case "switching-folder": return String(localized: "正在切换工作文件夹…")
        case "thinking": return String(localized: "正在思考…")
        default: return String(localized: "正在处理…")
        }
    }

    var body: some View {
        HStack(spacing: 8) {
            BotAvatar(chat: author, roster: roster, size: 28, main: main)
                .accessibilityHidden(true)
            Text(title).lineLimit(1)
            TimelineView(.periodic(from: .now, by: 1)) { tick in
                let hostStart = work.startedAtMs.map { Date(timeIntervalSince1970: Double($0.int64Value) / 1_000) }
                let startedAt = min(hostStart ?? observedAt, observedAt)
                let elapsed = Int64(max(0, tick.date.timeIntervalSince(startedAt)))
                Text(String(format: String(localized: "· %lld 秒"), elapsed))
                    .monospacedDigit().lineLimit(1)
                    .layoutPriority(1)
                    .accessibilityIdentifier("bot.live-work-elapsed")
            }
        }
        .appFont(.system(size: 14))
        .foregroundStyle(Color("BotSecondary"))
        .frame(maxWidth: .infinity, alignment: .leading)
    }
}

private func botErrorText(_ code: String) -> String {
    switch code {
    case "bot-unavailable", "bot/not-found": return String(localized: "主机上的 DS-Bot 尚未启用，或版本暂不支持")
    case "bot-version-unsupported": return String(localized: "请更新主机上的 DS-Bot")
    case "not-connected": return String(localized: "主机连接已断开，重连后将同步聊天")
    case "bot/main-protected": return String(localized: "主 Bot 不能删除。")
    case "bot-delete-failed": return String(localized: "暂时无法删除此 Bot，请稍后重试。")
    case "bot-delete-unconfirmed": return String(localized: "尚未确认删除结果，请重新同步后核对。")
    case "bot-timeout": return String(localized: "同步超时，请稍后重试；发送中的消息请先核对")
    default: return String(localized: "聊天同步暂时中断，可以重新同步")
    }
}

struct BotRoleSheet: View {
    @ObservedObject var model: BotModeModel
    let id: String
    @Environment(\.dismiss) private var dismiss
    @Environment(\.colorScheme) private var colorScheme
    @Environment(\.horizontalSizeClass) private var horizontalSizeClass
    @State private var settings = false
    @State private var detent = PresentationDetent.large
    private var compactNight: Bool { colorScheme == .dark && horizontalSizeClass == .compact }
    private var cardDetent: PresentationDetent { .height(650) }
    private var chat: BotChat? { model.snapshot.chats.first { $0.id == id } }

    var body: some View {
        NavigationStack {
            if let chat {
                List {
                    Section {
                        VStack(spacing: 6) {
                            BotAvatar(chat: chat, size: 80, main: id == model.snapshot.mainBotId)
                            Text(chat.name).appFont(.largeTitle.bold())
                            if !chat.role.isEmpty { Text(chat.role).appFont(.subheadline).foregroundStyle(.secondary) }
                            if let description = chat.profile?.instructions, !description.isEmpty {
                                Text(description).appFont(.footnote).foregroundStyle(.secondary)
                                    .multilineTextAlignment(.center)
                            }
                        }
                        .frame(maxWidth: .infinity).padding(.vertical, 8)
                        .listRowBackground(Color.clear)
                    }
                    Section {
                        Group {
                            LabeledContent(String(localized: "模型"), value: modelName(chat.profile?.model ?? chat.profile?.appliedModel ?? model.snapshot.defaultModel))
                            LabeledContent(String(localized: "权限"), value: permissionName(chat.profile?.permission))
                            LabeledContent(String(localized: "工作文件夹"), value: chat.profile?.workDir ?? String(localized: "总工作区"))
                        }.listRowBackground(Color("BotCard"))
                    }
                    Section {
                        if model.snapshot.memoryAvailable {
                            NavigationLink {
                                BotRoleMemoryView(model: model, id: id)
                            } label: {
                                LabeledContent(String(localized: "记忆"), value: model.snapshot.roleDetails.map { String($0.memories.count) } ?? "—")
                            }.listRowBackground(Color("BotCard"))
                        }
                        NavigationLink {
                            BotRoleScheduleView(model: model, id: id)
                        } label: {
                            LabeledContent(String(localized: "定时任务"), value: String(model.snapshot.schedules.filter { $0.botId == id }.count))
                        }.accessibilityIdentifier("bot.role-schedules").listRowBackground(Color("BotCard"))
                        if let details = model.snapshot.roleDetails,
                           let input = details.inputTokens?.int64Value, let output = details.outputTokens?.int64Value {
                            LabeledContent(String(localized: "近 30 天用量"), value: (input + output).formatted())
                                .listRowBackground(Color("BotCard"))
                        }
                    }
                }.listStyle(.insetGrouped).scrollContentBackground(.hidden).background(Color("BotGroupedSurface"))
                    .navigationBarTitleDisplayMode(.inline)
                    .toolbar {
                        if colorScheme == .dark {
                            if #available(iOS 26.0, *) {
                                ToolbarItem(placement: .topBarTrailing) { nightRoleActions }.sharedBackgroundVisibility(.hidden)
                            } else {
                                ToolbarItem(placement: .topBarTrailing) { nightRoleActions }
                            }
                        } else {
                            ToolbarItem(placement: .topBarTrailing) { roleSettingsButton }
                            ToolbarItem(placement: .cancellationAction) { Button("关闭") { dismiss() } }
                        }
                    }
                    .navigationDestination(isPresented: $settings) {
                        BotRoleSettings(model: model, chat: chat, onClose: { dismiss() })
                    }

            }
        }
        .task(id: id) { model.openRole(id) }
        .onChangeCompat(of: chat != nil) { _, exists in if !exists { dismiss() } }
        .onChangeCompat(of: compactNight) { _, compact in detent = compact && !settings ? cardDetent : .large }
        .onChangeCompat(of: settings) { _, showingSettings in if !showingSettings && compactNight { detent = cardDetent } }
        .onAppear { if compactNight { detent = cardDetent } }
        .presentationDetents(compactNight ? [cardDetent, .large] : [.large], selection: $detent)
        .presentationDragIndicator(.visible)
        .modifier(BotSheetPresentation())
        .tint(Color("BotInk"))
    }

    private var roleSettingsButton: some View {
        Button { detent = .large; settings = true } label: { Image(systemName: "gearshape") }
            .accessibilityLabel("角色设置")
    }

    private var nightRoleActions: some View {
        HStack(spacing: 8) {
            Button { detent = .large; settings = true } label: {
                Image(systemName: "gearshape").frame(width: 38, height: 38)
            }.glassCircleButton().accessibilityLabel("角色设置")
            Button { dismiss() } label: {
                Image(systemName: "xmark").frame(width: 38, height: 38)
            }.glassCircleButton().accessibilityLabel("关闭")
        }
    }

    private func modelName(_ id: String?) -> String {
        model.snapshot.models.first { $0.id == id }?.title ?? id ?? "—"
    }

    private func permissionName(_ id: String?) -> String {
        model.snapshot.permissions.first { $0.id == id }?.title ?? id ?? "—"
    }
}

private struct BotRoleSettings: View {
    @ObservedObject var model: BotModeModel
    let chat: BotChat
    let onClose: () -> Void
    @Environment(\.colorScheme) private var colorScheme
    @State private var name: String
    @State private var tag: String
    @State private var instructions: String
    @State private var modelID: String
    @State private var effort: String
    @State private var workDir: String
    @State private var permission: String
    @State private var privateRole: Bool
    @State private var confirmFullAccess = false
    @State private var confirmCopy = false
    @State private var confirmDelete = false
    @State private var replacement: BotRoleSelection?

    init(model: BotModeModel, chat: BotChat, onClose: @escaping () -> Void) {
        self.model = model
        self.chat = chat
        self.onClose = onClose
        _name = State(initialValue: chat.name)
        _tag = State(initialValue: chat.role)
        _instructions = State(initialValue: chat.profile?.instructions ?? "")
        _modelID = State(initialValue: chat.profile?.model ?? "")
        _effort = State(initialValue: chat.profile?.effort ?? "")
        _workDir = State(initialValue: chat.profile?.workDir ?? "")
        _permission = State(initialValue: chat.profile?.permission ?? "")
        _privateRole = State(initialValue: chat.profile?.privateRole ?? false)
    }

    private var live: BotChat { model.snapshot.chats.first { $0.id == chat.id } ?? chat }
    private var canEdit: Bool { model.snapshot.connected && model.snapshot.roleSettingsSupported && model.snapshot.writable }
    private var editingDisabled: Bool { !canEdit || model.snapshot.roleSaving }
    private var effortRef: String { modelID.isEmpty ? (live.profile?.appliedModel ?? model.snapshot.defaultModel ?? "") : modelID }
    private var isMain: Bool { chat.id == model.snapshot.mainBotId }
    private var privacyHelp: String {
        if !privateRole {
            if isMain { return String(localized: "主 Bot 不能开启隐私。") }
            if model.snapshot.chats.contains(where: { $0.room && $0.memberIds.contains(chat.id) }) {
                return String(localized: "将此 Bot 移出所有群聊后，才能开启隐私。")
            }
            if workDir.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                return String(localized: "开启隐私前，请为此 Bot 设置独立的工作文件夹。")
            }
        }
        return String(localized: "开启后，其他 Bot 无法读取它的工作文件夹、记忆和对话。向其他 Bot 分享内容需你批准。")
    }
    private var changes: [String: Any] {
        var result: [String: Any] = [:]
        if name != live.name { result["name"] = name }
        if tag != live.role { result["role"] = tag }
        if instructions != (live.profile?.instructions ?? "") { result["instructions"] = instructions }
        if modelID != (live.profile?.model ?? "") { result["model"] = modelID.isEmpty ? NSNull() as Any : modelID }
        if effort != (live.profile?.effort ?? "") { result["effort"] = effort.isEmpty ? NSNull() as Any : effort }
        if workDir != (live.profile?.workDir ?? "") { result["workDir"] = workDir.isEmpty ? NSNull() as Any : workDir }
        if permission != (live.profile?.permission ?? "") { result["permission"] = permission.isEmpty ? NSNull() as Any : permission }
        if privateRole != (live.profile?.privateRole ?? false) { result["private"] = privateRole }
        return result
    }

    var body: some View {
        Form {
            Section {
                HStack(spacing: 12) {
                    BotAvatar(chat: live, size: 56, main: live.id == model.snapshot.mainBotId)
                    VStack(alignment: .leading, spacing: 4) {
                        Text(live.name).appFont(.title2.bold())
                        Text(live.role).appFont(.caption).foregroundStyle(.secondary)
                    }
                }.listRowBackground(Color.clear)
            }
            Section {
                LabeledContent(String(localized: "名字")) {
                    TextField("名字", text: $name).multilineTextAlignment(.trailing)
                }
                LabeledContent(String(localized: "标签")) {
                    TextField("标签", text: $tag).multilineTextAlignment(.trailing)
                }
            } header: {
                Text("资料")
            } footer: {
                Text("标签为选填，会显示在 Bot 名字下方。").appFont(SettingsTypography.description).foregroundStyle(.secondary)
            }
            .listRowBackground(Color("BotCard")).disabled(editingDisabled)
            Section {
                Picker("模型", selection: $modelID) {
                    Text("默认模型").tag("")
                    if !modelID.isEmpty && !model.snapshot.models.contains(where: { $0.id == modelID }) {
                        Text(modelID).tag(modelID)
                    }
                    ForEach(model.snapshot.models, id: \.id) { option in Text(option.title).tag(option.id) }
                }
                if !model.snapshot.efforts.isEmpty || !effort.isEmpty {
                    Picker("推理强度", selection: $effort) {
                        Text("默认").tag("")
                        if !effort.isEmpty && !model.snapshot.efforts.contains(where: { $0.id == effort }) { Text(effort).tag(effort) }
                        ForEach(model.snapshot.efforts, id: \.id) { value in Text(value.title).tag(value.id) }
                    }
                }
            } header: {
                Text("模型")
            } footer: {
                Text("模型更改从下一条消息开始生效。").appFont(SettingsTypography.description).foregroundStyle(.secondary)
            }
            .listRowBackground(Color("BotCard")).disabled(editingDisabled)
            Section {
                LabeledContent(String(localized: "工作文件夹")) {
                    TextField("总工作区", text: $workDir)
                        .multilineTextAlignment(.trailing).textInputAutocapitalization(.never).autocorrectionDisabled()
                }
                Picker("权限", selection: $permission) {
                    Text("默认权限").tag("")
                    if !permission.isEmpty && !model.snapshot.permissions.contains(where: { $0.id == permission }) {
                        Text(permission).tag(permission)
                    }
                    ForEach(model.snapshot.permissions, id: \.id) { option in Text(option.title).tag(option.id) }
                }
                Toggle("隐私", isOn: $privateRole).disabled(isMain)
            } header: {
                Text("工作区与权限")
            } footer: {
                VStack(alignment: .leading, spacing: 4) {
                    if permission == "danger-full-access" {
                        Text("允许修改工作区以外的文件，范围仍受主机系统权限限制。")
                    }
                    Text(privacyHelp)
                }.appFont(SettingsTypography.description).foregroundStyle(.secondary)
            }
            .listRowBackground(Color("BotCard")).disabled(editingDisabled)
            Section {
                TextEditor(text: $instructions).frame(minHeight: 88).accessibilityLabel("说明")
                    .overlay(alignment: .topLeading) {
                        if instructions.isEmpty {
                            Text("这个 Bot 负责什么…")
                                .appFont(.body)
                                .foregroundStyle(.tertiary)
                                .padding(.leading, 5).padding(.top, 8)
                                .allowsHitTesting(false).accessibilityHidden(true)
                        }
                    }
            } header: {
                Text("说明")
            } footer: {
                Text("这段说明会写入 Bot 的系统提示词。").appFont(SettingsTypography.description).foregroundStyle(.secondary)
            }
            .listRowBackground(Color("BotCard")).disabled(editingDisabled)
            Section {
                LabeledContent(String(localized: "电脑操控"), value: model.snapshot.computerEnabled
                    ? String(localized: "已开启") : String(localized: "已关闭"))
            } header: {
                Text("操控")
            } footer: {
                Text("各 Bot 的电脑操控授权可在 DS Bot 网页端管理。").appFont(SettingsTypography.description).foregroundStyle(.secondary)
            }
            .listRowBackground(Color("BotCard"))
            Section {
                if model.snapshot.memoryAvailable {
                    NavigationLink(String(localized: "记忆")) { BotRoleMemoryView(model: model, id: chat.id) }
                }
                NavigationLink(String(localized: "定时任务")) { BotRoleScheduleView(model: model, id: chat.id) }
            }.listRowBackground(Color("BotCard")).disabled(editingDisabled)
            if isMain {
                Section {
                    Menu("更换主 Bot") {
                        ForEach(model.snapshot.chats.filter { !$0.room && $0.id != chat.id && $0.profile?.privateRole != true }, id: \.id) { candidate in
                            Button(candidate.name) { replacement = BotRoleSelection(id: candidate.id) }
                        }
                    }
                } header: {
                    Text("主 Bot")
                } footer: {
                    Text("主 Bot 可以创建和修改团队 Bot，并管理群聊。").appFont(SettingsTypography.description).foregroundStyle(.secondary)
                }
                .listRowBackground(Color("BotCard")).disabled(editingDisabled)
            }
            Section {
                Button("复制一份") { confirmCopy = true }
                if model.snapshot.botDeletionSupported && !model.snapshot.isMainBot(id: chat.id) {
                    Button(role: .destructive) { confirmDelete = true } label: {
                        HStack {
                            Text("删除 Bot").foregroundStyle(.red)
                            Spacer()
                            Image(systemName: "chevron.right").font(.caption.weight(.semibold))
                                .foregroundStyle(.tertiary)
                        }
                    }.accessibilityIdentifier("bot.role-delete")
                }
            } header: {
                Text("管理")
            } footer: {
                Text("复制分工和模型，新 Bot 从空白记忆开始。").appFont(SettingsTypography.description).foregroundStyle(.secondary)
            }
            .listRowBackground(Color("BotCard")).disabled(editingDisabled)
            if let error = model.snapshot.roleError {
                Section { Text(botErrorText(error)).foregroundStyle(.red) }
            }
        }
        .scrollDismissesKeyboard(.interactively)
        .scrollContentBackground(.hidden)
        .background(Color("BotGroupedSurface"))
        .accessibilityIdentifier("bot.role-settings-form")
        .background(KeyboardDismissProbe())
        .task(id: effortRef) { if !effortRef.isEmpty { model.loadRoleEfforts(effortRef) } }
        .onChange(of: modelID) { _ in effort = "" }
        .navigationTitle("角色设置")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .confirmationAction) {
                if model.snapshot.roleSaving { ProgressView() }
                else if colorScheme == .dark && changes.isEmpty {
                    Button(action: onClose) { Image(systemName: "xmark") }.accessibilityLabel("关闭")
                }
                else {
                    Button("保存") {
                        if changes["permission"] as? String == "danger-full-access" { confirmFullAccess = true }
                        else { model.updateRole(chat.id, changes: changes) }
                    }.disabled(!canEdit || changes.isEmpty || name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
        .alert("确认授予完全权限？", isPresented: $confirmFullAccess) {
            Button("取消", role: .cancel) {}
            Button("确认", role: .destructive) { model.updateRole(chat.id, changes: changes) }
        }
        .alert("复制这个角色？", isPresented: $confirmCopy) {
            Button("取消", role: .cancel) {}
            Button("复制一份") { model.duplicateRole(chat.id) }
        }
        .alert("删除 Bot？", isPresented: $confirmDelete) {
            Button("取消", role: .cancel) {}
            Button("删除", role: .destructive) { model.deleteRole(chat.id) }
        } message: {
            Text(String(format: String(localized: "将“%@”移出团队和所在群聊。"), live.name))
        }
        .alert("更换主 Bot？", isPresented: Binding(get: { replacement != nil }, set: { if !$0 { replacement = nil } })) {
            Button("取消", role: .cancel) { replacement = nil }
            Button("确认") {
                if let replacement { model.replacePrimaryRole(chat.id, replacement: replacement.id) }
                replacement = nil
            }
        }
    }
}

