private struct BotRoleMemoryView: View {
    @ObservedObject var model: BotModeModel
    let id: String
    @State private var editing: BotMemory?
    @State private var deleting: BotMemory?
    @State private var text = ""
    @State private var showsEditor = false

    var body: some View {
        List {
            let memories = model.snapshot.roleDetails?.memories ?? []
            if memories.isEmpty { Text("还没有记忆").foregroundStyle(.secondary) }
            ForEach(memories, id: \.id) { entry in
                Button {
                    editing = entry
                    text = entry.text
                    showsEditor = true
                } label: { Text(entry.text).foregroundStyle(.primary) }
                    .disabled(!canEdit)
                    .accessibilityIdentifier("bot.role-memory." + entry.id)
                    .swipeActions {
                        if canEdit { Button("删除", role: .destructive) { deleting = entry } }
                    }
            }
            if let error = model.snapshot.roleError { Text(botErrorText(error)).foregroundStyle(.red) }
        }
        .navigationTitle("记忆").navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .topBarTrailing) {
                Button { editing = nil; text = ""; showsEditor = true } label: { Image(systemName: "plus") }
                    .accessibilityLabel("添加记忆").disabled(!canEdit)
            }
        }
        .navigationDestination(isPresented: $showsEditor) {
            TextEditor(text: $text)
                .appFont(.body)
                .scrollContentBackground(.hidden)
                .overlay(alignment: .topLeading) {
                    if text.isEmpty {
                        Text("记忆")
                            .appFont(.body)
                            .foregroundStyle(.tertiary)
                            .padding(.leading, 5)
                            .padding(.top, 8)
                            .allowsHitTesting(false)
                            .accessibilityHidden(true)
                    }
                }
                .accessibilityLabel("记忆")
                .accessibilityIdentifier("bot.memory-editor")
                .padding(12)
                .background(Color("BotCard"), in: RoundedRectangle(cornerRadius: 20))
                .padding(16)
                .background(Color("BotGroupedSurface"))
                .background(KeyboardDismissProbe())
                .navigationTitle(editing == nil ? Text("添加记忆") : Text("编辑记忆"))
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    ToolbarItem(placement: .confirmationAction) {
                        Button("保存") {
                            model.saveRoleMemory(id, entryID: editing?.id, text: text)
                            showsEditor = false
                        }
                        .disabled(!canEdit || text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                    }
                }
        }
        .alert("删除这条记忆？", isPresented: Binding(get: { deleting != nil }, set: { if !$0 { deleting = nil } })) {
            Button("取消", role: .cancel) { deleting = nil }
            Button("删除", role: .destructive) {
                if let deleting { model.forgetRoleMemory(id, entryID: deleting.id) }
                deleting = nil
            }
        }
    }

    private var canEdit: Bool {
        model.snapshot.connected && model.snapshot.writable && model.snapshot.roleSettingsSupported && !model.snapshot.roleSaving
    }
}

private struct BotRoleScheduleView: View {
    @ObservedObject var model: BotModeModel
    let id: String
    @State private var creating = false
    @State private var deleting: BotSchedule?
    @State private var title = ""
    @State private var prompt = ""
    @State private var time = Date()

    var body: some View {
        List {
            let schedules = model.snapshot.schedules.filter { $0.botId == id }
            if schedules.isEmpty { Text("还没有定时任务").foregroundStyle(.secondary) }
            ForEach(schedules, id: \.id) { task in
                LabeledContent(task.title, value: task.next)
                    .accessibilityIdentifier("bot.role-schedule." + task.id)
                    .swipeActions {
                        if canEdit, let sessionID = task.sessionId,
                           !sessionID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            Button("删除", role: .destructive) { deleting = task }
                        }
                    }
            }
            if let error = model.snapshot.roleError { Text(botErrorText(error)).foregroundStyle(.red) }
        }.navigationTitle("定时任务").navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button { title = ""; prompt = ""; time = Date(); creating = true } label: { Image(systemName: "plus") }
                        .accessibilityLabel("新建定时任务").disabled(!canEdit)
                }
            }
            .navigationDestination(isPresented: $creating) {
                Form {
                    TextField("任务名称", text: $title)
                    TextField("任务内容", text: $prompt, axis: .vertical)
                    DatePicker("每天运行时间", selection: $time, displayedComponents: .hourAndMinute)
                        .accessibilityIdentifier("bot.role-schedule-time")
                }.navigationTitle("新建定时任务").navigationBarTitleDisplayMode(.inline)
                    .toolbar {
                        ToolbarItem(placement: .confirmationAction) {
                            Button("保存") {
                                model.scheduleRoleDaily(id, title: title, prompt: prompt, at: time)
                                creating = false
                            }.disabled(!canEdit || title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                || prompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                        }
                    }
            }
            .alert("删除这个定时任务？", isPresented: Binding(get: { deleting != nil }, set: { if !$0 { deleting = nil } })) {
                Button("取消", role: .cancel) { deleting = nil }
                Button("删除", role: .destructive) {
                    if let deleting { model.deleteRoleSchedule(id, taskID: deleting.id) }
                    deleting = nil
                }
            }
    }

    private var canEdit: Bool {
        model.snapshot.connected && model.snapshot.writable && model.snapshot.roleSettingsSupported
            && model.snapshot.schedulesAvailable && !model.snapshot.roleSaving
    }
}
